import json
from pathlib import Path


def sub(path, old, new, n=1):
    p=Path(path); s=p.read_text()
    if s.count(old) < n: raise SystemExit(f'{path}: missing {old[:80]!r}')
    p.write_text(s.replace(old,new,n))

