schema['title']='Codex local storage, replay, and projection semantics'
schema['properties']['$schema']={'const':schema['$id']}
for k in ('read_paths','projection_semantics'):
    if k not in schema['required']: schema['required'].append(k)
schema['properties']['read_paths']={"type":"object","additionalProperties":False,"required":["cold_resume_model_context","paginated_query_history"],"properties":{
 "cold_resume_model_context":{"type":"object","additionalProperties":False,"required":["selected_rollout_authority","source","reader","scan","uses_thread_history_projection"],"properties":{"selected_rollout_authority":{"type":"string"},"source":{"const":"selected immutable rollout JSONL lineage"},"reader":{"const":"load_latest_model_context"},"scan":{"type":"string"},"uses_thread_history_projection":{"const":False}}},
 "paginated_query_history":{"type":"object","additionalProperties":False,"required":["source","apis","persists_across_restart","full_replay_on_restart"],"properties":{"source":{"const":"$SQLITE_HOME/thread_history_1.sqlite"},"apis":{"const":["list_turns","list_items"]},"persists_across_restart":{"const":True},"full_replay_on_restart":{"const":False}}}}}
schema['properties']['projection_semantics']={"type":"object","additionalProperties":False,"required":["canonical_source","projection","role","write_order","checkpoint","update_mode","projected_prefix_must_be_immutable","may_lag_after_failure","may_get_ahead","rebuild_on_restart","external_rewrite"],"properties":{
 "canonical_source":{"const":"rollout JSONL"},"projection":{"const":"$SQLITE_HOME/thread_history_1.sqlite"},"role":{"const":"persistent rebuildable acceleration view"},"write_order":{"const":["durable JSONL write","incremental SQLite projection"]},"checkpoint":{"const":["next_rollout_byte_offset","next_rollout_ordinal"]},"update_mode":{"type":"string"},"projected_prefix_must_be_immutable":{"const":True},"may_lag_after_failure":{"const":True},"may_get_ahead":{"const":False},"rebuild_on_restart":{"const":False},"external_rewrite":{"type":"object","additionalProperties":False,"required":["supported","shrink_error","automatic_reset"],"properties":{"supported":{"const":False},"shrink_error":{"const":"durable rollout shrank before projection"},"automatic_reset":{"const":False}}}}}
